    var totalTimespan = TimeSpan.FromHours(hours);
    var todayEnd = date.Date + dayEnd;


    if (todayEnd - date > totalTimespan)
    {
        return date + totalTimespan;
    }

    var finishingDate = date.AddBusinessDays(1);
    var todayPortion = todayEnd - date;
    var remainigSpan = totalTimespan - todayPortion;
    var wholeDays = Convert.ToInt32(Math.Floor(remainigSpan.TotalHours / Constants.WorkdayLength.TotalHours));
    remainigSpan = remainigSpan - TimeSpan.FromHours(wholeDays * Constants.WorkdayLength.TotalHours);

    finishingDate = finishingDate.AddBusinessDays(wholeDays).Date + dayBegin + remainigSpan;

    return finishingDate;

